     1	import type {
     2	  MailFnClock,
     3	  MailFnIdGenerator,
     4	  MailFnSecretProtector,
     5	  MailFnTokenCodec,
     6	} from './contracts.js';
     7	
     8	const encoder = new TextEncoder();
     9	
    10	function bytesToHex(bytes: Uint8Array): string {
    11	  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
    12	}
    13	
    14	function randomHex(bytes: number): string {
    15	  const value = new Uint8Array(bytes);
    16	  globalThis.crypto.getRandomValues(value);
    17	  return bytesToHex(value);
    18	}
    19	
    20	export const systemClock: MailFnClock = {
    21	  now: () => new Date(),
    22	  sleep(ms, signal) {
    23	    if (signal?.aborted) return Promise.reject(new DOMException('Aborted', 'AbortError'));
    24	    return new Promise<void>((resolve, reject) => {
    25	      const timer = setTimeout(resolve, Math.max(0, ms));
    26	      signal?.addEventListener(
    27	        'abort',
    28	        () => {
    29	          clearTimeout(timer);
    30	          reject(new DOMException('Aborted', 'AbortError'));
    31	        },
    32	        { once: true },
    33	      );
    34	    });
    35	  },
    36	};
    37	
    38	export const defaultIdGenerator: MailFnIdGenerator = {
    39	  generate(prefix) {
    40	    return `${prefix}_${globalThis.crypto.randomUUID().replaceAll('-', '')}`;
    41	  },
    42	};
    43	
    44	export const sha256TokenCodec: MailFnTokenCodec = {
    45	  async create(credentialId) {
    46	    const secret = randomHex(32);
    47	    const token = `mfn_${credentialId}_${secret}`;
    48	    return {
    49	      token,
    50	      hash: await this.hash(token),
    51	      prefix: token.slice(0, Math.min(24, token.length)),
    52	    };
    53	  },
    54	  async hash(token) {
    55	    const digest = await globalThis.crypto.subtle.digest('SHA-256', encoder.encode(token));
    56	    return bytesToHex(new Uint8Array(digest));
    57	  },
    58	  equals(left, right) {
    59	    if (left.length !== right.length) return false;
    60	    let difference = 0;
    61	    for (let index = 0; index < left.length; index += 1) {
    62	      difference |= left.charCodeAt(index) ^ right.charCodeAt(index);
    63	    }
    64	    return difference === 0;
    65	  },
    66	};
