    68	export function createAesGcmSecretProtector(key: CryptoKey): MailFnSecretProtector {
    69	  return {
    70	    async protect(secret) {
    71	      const iv = globalThis.crypto.getRandomValues(new Uint8Array(12));
    72	      const ciphertext = await globalThis.crypto.subtle.encrypt(
    73	        { name: 'AES-GCM', iv },
    74	        key,
    75	        encoder.encode(secret),
    76	      );
    77	      return `${bytesToHex(iv)}.${bytesToHex(new Uint8Array(ciphertext))}`;
    78	    },
    79	    async reveal(value) {
    80	      const [ivHex, ciphertextHex] = value.split('.');
    81	      if (!ivHex || !ciphertextHex) throw new Error('MAILFN_SECRET_CIPHERTEXT_INVALID');
    82	      const fromHex = (hex: string) => Uint8Array.from(hex.match(/.{2}/g) ?? [], (part) => Number.parseInt(part, 16));
    83	      const plaintext = await globalThis.crypto.subtle.decrypt(
    84	        { name: 'AES-GCM', iv: fromHex(ivHex) },
    85	        key,
    86	        fromHex(ciphertextHex),
    87	      );
    88	      return new TextDecoder().decode(plaintext);
    89	    },
    90	  };
    91	}
