     1	import type { ExtractedVerification, Message } from './types.js';
     2	
     3	const OTP_PATTERNS = [
     4	  /(?:verification|security|login|one[- ]time|auth(?:entication)?|confirm(?:ation)?)\s*(?:code|pin|otp)?\s*(?:is|:|-)?\s*([0-9]{4,10})/i,
     5	  /\b([0-9]{6})\b/,
     6	];
     7	
     8	const LINK_PATTERN = /https?:\/\/[^\s<>"']+/gi;
     9	const VERIFY_TERMS = /verify|verification|confirm|activate|magic|login|reset|recover/i;
    10	
    11	export function extractOtp(message: Message): ExtractedVerification | null {
    12	  for (const [field, value] of verificationFields(message)) {
    13	    const plain = stripMarkup(value);
    14	    for (const pattern of OTP_PATTERNS) {
    15	      const match = pattern.exec(plain);
    16	      if (match?.[1]) {
    17	        return source(message, 'otp', match[1], field);
    18	      }
    19	    }
    20	  }
    21	  return null;
    22	}
    23	
    24	export function extractVerificationLink(message: Message): ExtractedVerification | null {
    25	  const candidates: Array<{ value: string; field: 'subject' | 'text' | 'html'; score: number }> = [];
    26	  for (const [field, value] of verificationFields(message)) {
    27	    const matches = value.match(LINK_PATTERN) ?? [];
    28	    for (const raw of matches) {
    29	      const normalized = raw.replace(/&amp;/g, '&').replace(/[).,;]+$/, '');
    30	      let parsed: URL;
    31	      try {
    32	        parsed = new URL(normalized);
    33	      } catch {
    34	        continue;
    35	      }
    36	      if (!['http:', 'https:'].includes(parsed.protocol)) continue;
    37	      const score =
    38	        (VERIFY_TERMS.test(parsed.pathname) ? 4 : 0) +
    39	        (VERIFY_TERMS.test(parsed.search) ? 3 : 0) +
    40	        (parsed.searchParams.has('token') || parsed.searchParams.has('code') ? 2 : 0) +
    41	        (field === 'html' ? 1 : 0);
    42	      candidates.push({ value: parsed.toString(), field, score });
    43	    }
    44	  }
    45	  candidates.sort((left, right) => right.score - left.score || left.value.localeCompare(right.value));
    46	  const selected = candidates[0];
    47	  return selected ? source(message, 'verification_link', selected.value, selected.field) : null;
    48	}
    49	
    50	function verificationFields(message: Message): Array<['subject' | 'text' | 'html', string]> {
    51	  return [
    52	    ['subject', message.subject],
    53	    ['text', message.textBody ?? ''],
    54	    ['html', message.htmlBody ?? ''],
    55	  ];
    56	}
    57	
    58	function stripMarkup(value: string): string {
    59	  return value.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ');
    60	}
    61	
    62	function source(
    63	  message: Message,
    64	  type: ExtractedVerification['type'],
    65	  value: string,
    66	  matchedField: ExtractedVerification['matchedField'],
    67	): ExtractedVerification {
    68	  return {
    69	    type,
    70	    value,
    71	    sourceMessageId: message.id,
    72	    receivedAt: message.receivedAt,
    73	    matchedField,
    74	  };
    75	}

