     1	import type { MailFnIdGenerator } from './contracts.js';
     2	import type { Message, Thread } from './types.js';
     3	
     4	const PREFIX_PATTERN = /^\s*(?:(?:re|fw|fwd)\s*:\s*)+/i;
     5	
     6	export function normalizeThreadSubject(subject: string): string {
     7	  return subject.replace(PREFIX_PATTERN, '').replace(/\s+/g, ' ').trim().toLowerCase() || '(no subject)';
     8	}
     9	
    10	export function resolveThread(
    11	  message: Message,
    12	  existing: Thread[],
    13	  messages: Message[],
    14	  ids: MailFnIdGenerator,
    15	  now: string,
    16	): Thread {
    17	  const referenceIds = new Set([message.inReplyTo, ...message.references].filter(Boolean));
    18	  const parent = messages.find(
    19	    (candidate) => candidate.internetMessageId && referenceIds.has(candidate.internetMessageId),
    20	  );
    21	  const normalizedSubject = normalizeThreadSubject(message.subject);
    22	  const found =
    23	    (parent?.threadId ? existing.find((thread) => thread.id === parent.threadId) : undefined) ??
    24	    existing.find((thread) => thread.normalizedSubject === normalizedSubject);
    25	  const participants = [
    26	    ...message.from.map((entry) => entry.address),
    27	    ...message.to.map((entry) => entry.address),
    28	    ...message.cc.map((entry) => entry.address),
    29	  ];
    30	
    31	  if (found) {
    32	    return {
    33	      ...found,
    34	      messageIds: Array.from(new Set([...found.messageIds, message.id])),
    35	      participants: Array.from(new Set([...found.participants, ...participants])).sort(),
    36	      lastMessageAt: message.receivedAt > found.lastMessageAt ? message.receivedAt : found.lastMessageAt,
    37	      updatedAt: now,
    38	    };
    39	  }
    40	
    41	  return {
    42	    id: ids.generate('thr'),
    43	    projectId: message.projectId,
    44	    inboxId: message.inboxId,
    45	    normalizedSubject,
    46	    messageIds: [message.id],
    47	    participants: Array.from(new Set(participants)).sort(),
    48	    labels: [],
    49	    lastMessageAt: message.receivedAt,
    50	    createdAt: now,
    51	    updatedAt: now,
    52	  };
    53	}

