  1388	  private async dispatchEvent(event: MailFnEvent): Promise<void> {
  1389	    if (!this.webhookDispatcher || !this.secretProtector) return;
  1390	    const webhooks = (await this.store.listWebhooks(event.projectId)).filter(
  1391	      (webhook) =>
  1392	        webhook.status === 'active' &&
  1393	        webhook.eventTypes.includes(event.type) &&
  1394	        (!webhook.inboxId || webhook.inboxId === event.inboxId),
  1395	    );
  1396	    for (const webhook of webhooks) {
  1397	      const now = this.now();
  1398	      const delivery: WebhookDelivery = {
  1399	        id: this.ids.generate('whd'),
  1400	        webhookId: webhook.id,
  1401	        eventId: event.id,
  1402	        attempt: 1,
  1403	        status: 'pending',
  1404	        createdAt: now,
  1405	        updatedAt: now,
  1406	      };
  1407	      await this.store.saveWebhookDelivery(delivery);
  1408	      const result = await this.deliverWebhook(webhook, event, delivery);
  1409	      if (!result.ok && event.type !== 'webhook.delivery_failed') {
  1410	        await this.event('webhook.delivery_failed', event.projectId, {
  1411	          inboxId: event.inboxId,
  1412	          messageId: event.messageId,
  1413	          payload: { webhookId: webhook.id, deliveryId: delivery.id, retryable: result.retryable },
  1414	        });
  1415	      }
  1416	    }
  1417	  }
  1418	
  1419	  private async deliverWebhook(
  1420	    webhook: Webhook,
  1421	    event: MailFnEvent,
  1422	    delivery: WebhookDelivery,
  1423	  ): Promise<{ ok: boolean; status?: number; retryable: boolean }> {
  1424	    const protectedSecret = webhook.secretCiphertext;
  1425	    let result: { ok: boolean; status?: number; retryable: boolean };
  1426	    if (!protectedSecret) {
  1427	      result = { ok: false, retryable: false };
  1428	    } else {
  1429	      try {
  1430	        result = await this.webhookDispatcher!.deliver({
  1431	          webhook: { ...webhook, secretCiphertext: await this.secretProtector!.reveal(protectedSecret) },
  1432	          event,
  1433	          deliveryId: delivery.id,
  1434	          timestamp: this.now(),
  1435	        });
  1436	      } catch {
  1437	        // Webhook delivery is an independent, retryable side effect. A consumer
  1438	        // outage must never roll back a successfully accepted inbound message.
  1439	        result = { ok: false, retryable: true };
  1440	      }
  1441	    }
  1442	    const failures = result.ok ? 0 : webhook.consecutiveFailures + 1;
  1443	    const retryable = !result.ok && result.retryable && delivery.attempt < 8;
  1444	    await this.store.saveWebhook({
  1445	      ...webhook,
  1446	      consecutiveFailures: failures,
  1447	      status: failures >= 10 ? 'quarantined' : webhook.status,
  1448	      updatedAt: this.now(),
  1449	    });
  1450	    await this.store.saveWebhookDelivery({
  1451	      ...delivery,
  1452	      status: result.ok ? 'delivered' : retryable ? 'failed' : 'dead_letter',
  1453	      responseStatus: result.status,
  1454	      nextAttemptAt: retryable
  1455	        ? new Date(this.clock.now().getTime() + Math.min(3_600, 2 ** delivery.attempt) * 1_000).toISOString()
  1456	        : undefined,
  1457	      updatedAt: this.now(),
  1458	    });
  1459	    return result;
  1460	  }

 779	  public async waitForMessages(actor: Actor, input: Omit<WaitForMessageInput, 'projectId'>): Promise<WaitForMessageResult> {
 780	    await this.authorize(actor, 'message:wait', actor.projectId, input.inboxId);
 781	    await this.requireInbox(actor.projectId, input.inboxId);
 782	    validateMessageFilter(input);
 783	    validateIsoFilter(input.after, 'after');
 784	    const timeoutMs = boundedNumber(input.timeoutMs, 30_000, 0, 120_000, 'timeoutMs');
 785	    const pollIntervalMs = boundedNumber(input.pollIntervalMs, 250, 50, 5_000, 'pollIntervalMs');
 786	    const expectedCount = boundedInteger(input.expectedCount, 1, 1, 100, 'expectedCount');
 787	    const deadline = this.clock.now().getTime() + timeoutMs;
 788	    while (true) {
 789	      if (input.signal?.aborted) {
 790	        throw new MailFnError({ code: 'MAILFN_ABORTED', message: 'Wait was cancelled', status: 499 });
 791	      }
 792	      const messages = await this.store.listMessages(actor.projectId, input.inboxId, {
 793	        ...input,
 794	        receivedAfter: input.after ?? input.receivedAfter,
 795	        status: input.status ?? 'ready',
 796	      });
 797	      if (messages.length >= expectedCount) {
 798	        return { status: 'matched', messages: messages.slice(0, expectedCount), matchedAt: this.now() };
 799	      }
 800	      const remaining = deadline - this.clock.now().getTime();
 801	      if (remaining <= 0) return { status: 'timeout', messages: [], timedOutAt: this.now(), retryable: true };
 802	      try {
 803	        await this.clock.sleep(Math.min(pollIntervalMs, remaining), input.signal);
 804	      } catch (error) {
 805	        if (error instanceof DOMException && error.name === 'AbortError') {
 806	          throw new MailFnError({ code: 'MAILFN_ABORTED', message: 'Wait was cancelled', status: 499 });
 807	        }
 808	        throw error;
 809	      }
 810	    }
 811	  }
