     4	interface PostalAddress {
     5	  address?: string;
     6	  name?: string;
     7	  group?: PostalAddress[];
     8	}
     9	
    10	interface PostalResult {
    11	  messageId?: string;
    12	  subject?: string;
    13	  text?: string;
    14	  html?: string;
    15	  from?: PostalAddress;
    16	  to?: PostalAddress[];
    17	  cc?: PostalAddress[];
    18	  bcc?: PostalAddress[];
