    28	    disposition?: string;
    29	  }>;
    30	}
    31	
    32	export class PostalMimeParser implements MailFnMimeParser {
    33	  public async parse(raw: Uint8Array): Promise<ParsedMessage> {
    34	    const parsed = (await PostalMime.parse(Uint8Array.from(raw))) as PostalResult;
    35	    const headers: Record<string, string[]> = {};
    36	    for (const header of parsed.headers ?? []) {
    37	      const key = header.key.toLowerCase();
    38	      (headers[key] ??= []).push(header.value);
    39	    }
    40	    const authenticationRaw = headers['authentication-results']?.join('; ');
    41	    return {
    42	      internetMessageId: parsed.messageId ?? first(headers, 'message-id'),
    43	      from: flatten(parsed.from ? [parsed.from] : []),
    44	      to: flatten(parsed.to ?? []),
    45	      cc: flatten(parsed.cc ?? []),
    46	      bcc: flatten(parsed.bcc ?? []),
    47	      replyTo: flatten(parsed.replyTo ?? []),
    48	      subject: parsed.subject,
    49	      text: parsed.text,
    50	      html: parsed.html,
    51	      headers,
    52	      inReplyTo: parsed.inReplyTo ?? first(headers, 'in-reply-to'),
    53	      references: normalizeReferences(parsed.references ?? first(headers, 'references')),
    54	      authenticationResults: authenticationRaw
    55	        ? {
    56	            raw: authenticationRaw,
    57	            spf: result(authenticationRaw, 'spf'),
    58	            dkim: result(authenticationRaw, 'dkim'),
    59	            dmarc: result(authenticationRaw, 'dmarc'),
    60	            arc: result(authenticationRaw, 'arc'),
    61	          }
    62	        : undefined,
    63	      attachments: (parsed.attachments ?? []).map((attachment) => ({
    64	        filename: attachment.filename,
    65	        contentType: attachment.mimeType,
    66	        content: bytes(attachment.content),
    67	        contentId: attachment.contentId,
    68	        disposition: attachment.disposition,
    69	      })),
