    81	  );
    82	}
    83	
    84	function first(headers: Record<string, string[]>, key: string): string | undefined {
    85	  return headers[key]?.[0];
    86	}
    87	
    88	function normalizeReferences(value: string | string[] | undefined): string[] {
    89	  if (!value) return [];
    90	  const joined = Array.isArray(value) ? value.join(' ') : value;
    91	  return Array.from(joined.matchAll(/<[^>]+>/g), (match) => match[0]);
    92	}
