    98	function bytes(value: Uint8Array | ArrayBuffer | string | undefined): Uint8Array {
    99	  if (value instanceof Uint8Array) return Uint8Array.from(value);
   100	  if (value instanceof ArrayBuffer) return new Uint8Array(value);
   101	  if (typeof value === 'string') return new TextEncoder().encode(value);
