   100	function redact(value: unknown, showContent: boolean): unknown {
   101	  if (showContent || value === null || typeof value !== 'object') return value;
   102	  if (Array.isArray(value)) return value.map((entry) => redact(entry, false));
   103	  return Object.fromEntries(
   104	    Object.entries(value as Record<string, unknown>).map(([key, entry]) => [
   105	      key,
   106	      /textBody|htmlBody|token|secret|verification|raw/i.test(key) ? '[REDACTED]' : redact(entry, false),
   107	    ]),
   108	  );
   109	}
