   111	function parse(args: string[]): {
   112	  command: string;
   113	  positionals: string[];
   114	  flags: Record<string, string | boolean | undefined>;
   115	} {
   116	  const [noun, verb, ...rest] = args;
   117	  if (!noun || noun === '--help' || noun === 'help') return { command: 'help', positionals: [], flags: {} };
   118	  const command = verb && !verb.startsWith('-') ? `${noun}:${verb}` : noun;
   119	  const values = verb && !verb.startsWith('-') ? rest : [verb, ...rest].filter(Boolean) as string[];
   120	  const positionals: string[] = [];
   121	  const flags: Record<string, string | boolean> = {};
   122	  for (let index = 0; index < values.length; index += 1) {
   123	    const value = values[index]!;
   124	    if (!value.startsWith('--')) { positionals.push(value); continue; }
   125	    const key = value.slice(2).replace(/-([a-z])/g, (_, letter: string) => letter.toUpperCase());
   126	    const next = values[index + 1];
   127	    if (next && !next.startsWith('--')) { flags[key] = next; index += 1; }
   128	    else flags[key] = true;
   129	  }
   130	  return { command, positionals, flags };
   131	}
