 135	export async function serveMailFnMcpStdio(client: MailFnClient, signal?: AbortSignal): Promise<void> {
 136	  const server = new MailFnMcpServer(client);
 137	  let buffer = Buffer.alloc(0);
 138	  const onData = (chunk: Buffer | string) => {
 139	    buffer = Buffer.concat([buffer, typeof chunk === 'string' ? Buffer.from(chunk) : chunk]);
 140	    while (true) {
 141	      const headerEnd = buffer.indexOf('\r\n\r\n');
 142	      if (headerEnd < 0) return;
 143	      const match = buffer.subarray(0, headerEnd).toString('utf8').match(/Content-Length:\s*(\d+)/i);
 144	      if (!match) { buffer = Buffer.alloc(0); return; }
 145	      const length = Number.parseInt(match[1]!, 10);
 146	      const start = headerEnd + 4;
 147	      if (buffer.length < start + length) return;
 148	      const request = JSON.parse(buffer.subarray(start, start + length).toString('utf8')) as JsonRpcRequest;
 149	      buffer = buffer.subarray(start + length);
 150	      void server.handleRequest(request).then((result) => result && write(result));
 151	    }
 152	  };
 153	  process.stdin.on('data', onData);
 154	  await new Promise<void>((resolve) => {
 155	    const close = () => { process.stdin.off('data', onData); resolve(); };
 156	    process.stdin.once('end', close);
 157	    signal?.addEventListener('abort', close, { once: true });
 158	  });
 159	}
