 163	  const frame = Buffer.concat([Buffer.from(`Content-Length: ${body.byteLength}\r\n\r\n`), body]);
 164	  return new Promise((resolve, reject) => process.stdout.write(frame, (error) => error ? reject(error) : resolve()));
