   192	    const hash = await this.tokens.hash(token);
   193	    if (!this.tokens.equals(hash, credential.tokenHash)) throw unauthorized();
   194	    await this.store.saveCredential({ ...credential, lastUsedAt: now });
   195	    return {
   196	      actorType: 'credential',
   197	      actorId: credential.id,
   198	      projectId: credential.projectId,
   199	      inboxId: credential.inboxId,
