 113	export function assertMessage(input: {
 114	  message: Message;
 115	  sender?: string;
 116	  recipient?: string;
 117	  subjectIncludes?: string;
 118	  textIncludes?: string;
 119	  header?: { name: string; includes: string };
 120	  attachment?: { filename?: string; contentType?: string };
 121	  attachments?: Array<{ filename: string; contentType: string }>;
 122	}): void {
 123	  const { message } = input;
 124	  const sender = input.sender?.toLowerCase();
 125	  if (sender && !message.from.some((entry) => entry.address === sender)) {
 126	    throw new MailFnAssertionError(`Expected sender ${sender}`);
 127	  }
 128	  const recipient = input.recipient?.toLowerCase();
 129	  if (recipient && !message.to.some((entry) => entry.address === recipient)) {
 130	    throw new MailFnAssertionError(`Expected recipient ${recipient}`);
 131	  }
 132	  if (input.subjectIncludes && !message.subject.includes(input.subjectIncludes)) {
 133	    throw new MailFnAssertionError(`Expected subject to include ${input.subjectIncludes}`);
 134	  }
 135	  if (input.textIncludes && !`${message.textBody ?? ''}\n${message.htmlBody ?? ''}`.includes(input.textIncludes)) {
 136	    throw new MailFnAssertionError(`Expected message content to include ${input.textIncludes}`);
 137	  }
 138	  if (input.header) {
 139	    const values = Object.entries(message.headers).find(([name]) => name.toLowerCase() === input.header!.name.toLowerCase())?.[1] ?? [];
 140	    if (!values.some((value) => value.includes(input.header!.includes))) {
 141	      throw new MailFnAssertionError(`Expected header ${input.header.name} to include ${input.header.includes}`);
 142	    }
 143	  }
 144	  if (input.attachment || input.attachments) {
 145	    throw new MailFnAssertionError('Attachment assertions require assertAttachments with retrieved metadata');
 146	  }
 147	}
