   200	  public async authenticate(token: string): Promise<Actor> {
   201	    const match = /^mfn_(.+)_([a-f0-9]{64})$/.exec(token);
   202	    if (!match?.[1]) throw unauthorized();
   203	    const credential = await this.store.getCredential(match[1]);
   204	    if (!credential || credential.status !== 'active') throw unauthorized();
   205	    const now = this.now();
   206	    if (credential.expiresAt && credential.expiresAt <= now) {
   207	      await this.store.saveCredential({ ...credential, status: 'expired' });
   208	      throw unauthorized();
   209	    }
   210	    const hash = await this.tokens.hash(token);
   211	    if (!this.tokens.equals(hash, credential.tokenHash)) throw unauthorized();
   212	    await this.store.saveCredential({ ...credential, lastUsedAt: now });
   213	    return {
   214	      actorType: 'credential',
   215	      actorId: credential.id,
   216	      projectId: credential.projectId,
   217	      inboxId: credential.inboxId,
   218	      scopes: credential.permissions,
   219	    };
   220	  }
