   225	    });
   226	    await this.authorize(actor, 'token:manage', input.projectId, input.inboxId);
   227	    if (!actor.scopes.includes('project:admin')) {
   228	      assertMailFn(input.permissions.every((scope) => actor.scopes.includes(scope)), {
   229	        code: 'MAILFN_FORBIDDEN',
