   239	    if (input.inboxId) await this.requireInbox(input.projectId, input.inboxId);
   240	    const created = await this.issueCredential(input);
   241	    await this.audit(actor, 'credential.created', 'credential', created.credential.id, {
   242	      inboxId: input.inboxId ?? null,
   243	      scopeCount: input.permissions.length,
