1327	  public async runRetention(projectId?: string): Promise<RetentionResult> {
1328	    const result: RetentionResult = { expiredInboxes: 0, deletedMessages: 0, deletedObjects: 0, auditEventsDeleted: 0 };
1329	    const projects = projectId ? [await this.requireProject(projectId)] : await this.store.listProjects();
1330	    const now = this.now();
1331	    for (const project of projects) {
1332	      const compliance = await this.store.getComplianceProfile(project.id);
1333	      for (const inbox of await this.store.listInboxes(project.id)) {
1334	        let effectiveInbox = inbox;
1335	        if (inbox.status === 'active' && inbox.expiresAt && inbox.expiresAt <= now) {
1336	          effectiveInbox = { ...inbox, status: 'expired', updatedAt: now };
1337	          await this.store.saveInbox(effectiveInbox);
1338	          result.expiredInboxes += 1;
1339	          await this.event('inbox.expired', project.id, { inboxId: inbox.id, payload: {} });
1340	          for (const credential of await this.store.listCredentials(project.id, inbox.id)) {
1341	            if (credential.status === 'active') await this.store.saveCredential({ ...credential, status: 'expired' });
1342	          }
1343	        }
1344	        if (compliance?.retentionLocked) continue;
1345	        const messages = await this.store.listMessages(project.id, inbox.id);
1346	        for (const message of messages) {
1347	          const retention = effectiveInbox.kind === 'expiring' ? DEFAULT_EXPIRING_RETENTION : project.defaultRetentionPolicy;
1348	          const inboxDeletion = effectiveInbox.status === 'expired' && retention.deleteOnInboxExpiry;
1349	          if (message.retentionExpiresAt <= now || inboxDeletion) {
1350	            try {
1351	              result.deletedObjects += await this.deleteMessageObjects(message);
1352	              await this.store.deleteMessage(message.id);
1353	              result.deletedMessages += 1;
1354	              await this.event('retention.deleted', project.id, {
1355	                inboxId: inbox.id,
1356	                messageId: message.id,
1357	                payload: { reason: inboxDeletion ? 'inbox_expired' : 'message_expired' },
1358	              });
1359	            } catch {
1360	              await this.systemAudit(project.id, 'retention.delete_failed', 'message', message.id, {
1361	                objectType: 'message',
1362	              }).catch(() => undefined);
1363	            }
1364	            continue;
1365	          }
1366	          if (!message.rawDeletedAt && message.rawRetentionExpiresAt <= now) {
1367	            try {
1368	              await this.objects.delete(message.rawObjectKey);
1369	              await this.store.releaseStorage(message.id);
1370	              await this.store.saveMessage({ ...message, rawDeletedAt: now, updatedAt: now });
1371	              result.deletedObjects += 1;
1372	            } catch {
1373	              await this.systemAudit(project.id, 'retention.delete_failed', 'message', message.id, {
1374	                objectType: 'raw',
1375	              }).catch(() => undefined);
1376	            }
1377	          }
1378	          if (message.attachmentRetentionExpiresAt <= now) {
1379	            for (const attachment of await this.store.listAttachments(message.id)) {
1380	              try {
1381	                await this.objects.delete(attachment.objectKey);
1382	                await this.store.releaseStorage(attachment.id);
1383	                await this.store.deleteAttachment(attachment.id);
1384	                result.deletedObjects += 1;
1385	              } catch {
1386	                await this.systemAudit(project.id, 'retention.delete_failed', 'attachment', attachment.id, {
1387	                  objectType: 'attachment',
1388	                }).catch(() => undefined);
1389	              }
1390	            }
1391	          }
1392	        }
1393	      }
1394	      if (!compliance?.retentionLocked) {
1395	        result.auditEventsDeleted += await this.store.deleteExpiredAudits(project.id, now);
1396	      }
1397	    }
1398	    return result;
1399	  }
