1421	  public evaluateOperationalAlerts(snapshot: OperationalSnapshot): OperationalAlert[] {
1422	    const checks: Array<[keyof OperationalSnapshot, number, string]> = [
1423	      ['parseFailures', 5, 'MAILFN_PARSE_FAILURES_HIGH'],
1424	      ['queuedFailures', 1, 'MAILFN_QUEUE_FAILURES_PRESENT'],
1425	      ['webhookFailures', 10, 'MAILFN_WEBHOOK_FAILURES_HIGH'],
1426	      ['authorizationFailures', 50, 'MAILFN_AUTHORIZATION_FAILURES_HIGH'],
1427	    ];
1428	    return checks.flatMap(([key, threshold, code]) => {
1429	      const value = snapshot[key];
1430	      if (typeof value !== 'number' || value < threshold) return [];
1431	      return [{
1432	        code,
1433	        severity: value >= threshold * 5 ? 'critical' as const : 'warning' as const,
1434	        message: `${String(key)} reached ${value}`,
1435	        value,
1436	        threshold,
1437	      }];
1438	    });
1439	  }
