1844	  private async dispatchEvent(event: MailFnEvent): Promise<void> {
1845	    if (!this.webhookDispatcher || !this.secretProtector) return;
1846	    const webhooks = (await this.store.listWebhooks(event.projectId)).filter(
1847	      (webhook) =>
1848	        webhook.status === 'active' &&
1849	        webhook.eventTypes.includes(event.type) &&
1850	        (!webhook.inboxId || webhook.inboxId === event.inboxId),
1851	    );
1852	    for (const webhook of webhooks) {
1853	      const now = this.now();
1854	      const delivery: WebhookDelivery = {
1855	        id: this.ids.generate('whd'),
1856	        webhookId: webhook.id,
1857	        eventId: event.id,
1858	        attempt: 1,
1859	        status: 'pending',
1860	        createdAt: now,
1861	        updatedAt: now,
1862	      };
1863	      await this.store.saveWebhookDelivery(delivery);
1864	      const result = await this.deliverWebhook(webhook, event, delivery);
1865	      if (!result.ok && event.type !== 'webhook.delivery_failed') {
1866	        await this.event('webhook.delivery_failed', event.projectId, {
1867	          inboxId: event.inboxId,
1868	          messageId: event.messageId,
1869	          payload: { webhookId: webhook.id, deliveryId: delivery.id, retryable: result.retryable },
1870	        });
1871	      }
1872	    }
1873	  }
1874	
1875	  private async deliverWebhook(
1876	    webhook: Webhook,
1877	    event: MailFnEvent,
1878	    delivery: WebhookDelivery,
1879	  ): Promise<{ ok: boolean; status?: number; retryable: boolean }> {
1880	    const protectedSecret = webhook.secretCiphertext;
1881	    let result: { ok: boolean; status?: number; retryable: boolean };
1882	    if (!protectedSecret) {
1883	      result = { ok: false, retryable: false };
1884	    } else {
1885	      try {
1886	        result = await this.webhookDispatcher!.deliver({
1887	          webhook: { ...webhook, secretCiphertext: await this.secretProtector!.reveal(protectedSecret) },
1888	          event,
1889	          deliveryId: delivery.id,
1890	          timestamp: this.now(),
1891	        });
1892	      } catch {
1893	        // Webhook delivery is an independent, retryable side effect. A consumer
1894	        // outage must never roll back a successfully accepted inbound message.
1895	        result = { ok: false, retryable: true };
1896	      }
1897	    }
1898	    const failures = result.ok ? 0 : webhook.consecutiveFailures + 1;
1899	    const retryable = !result.ok && result.retryable && delivery.attempt < 8;
1900	    await this.store.saveWebhook({
1901	      ...webhook,
1902	      consecutiveFailures: failures,
1903	      status: failures >= 10 ? 'quarantined' : webhook.status,
1904	      updatedAt: this.now(),
1905	    });
1906	    await this.store.saveWebhookDelivery({
1907	      ...delivery,
1908	      status: result.ok ? 'delivered' : retryable ? 'failed' : 'dead_letter',
1909	      responseStatus: result.status,
1910	      nextAttemptAt: retryable
1911	        ? new Date(this.clock.now().getTime() + Math.min(3_600, 2 ** delivery.attempt) * 1_000).toISOString()
1912	        : undefined,
1913	      updatedAt: this.now(),
1914	    });
1915	    return result;
1916	  }
