148	export async function serveMailFnMcpStdio(
149	  client: MailFnClient,
150	  signal?: AbortSignal,
151	  streams: { input: Readable; output: Writable } = { input: process.stdin, output: process.stdout },
152	): Promise<void> {
153	  const server = new MailFnMcpServer(client);
154	  const lines = createInterface({ input: streams.input, crlfDelay: Infinity });
155	  const close = () => lines.close();
156	  signal?.addEventListener('abort', close, { once: true });
157	  try {
158	    for await (const line of lines) {
159	      if (!line.trim()) continue;
160	      let request: JsonRpcRequest;
161	      try {
162	        request = JSON.parse(line) as JsonRpcRequest;
163	      } catch {
164	        await write(failure({ jsonrpc: '2.0', id: null, method: '' }, -32700, 'Parse error'), streams.output);
165	        continue;
166	      }
167	      const result = await server.handleRequest(request);
168	      if (result) await write(result, streams.output);
169	    }
170	  } finally {
171	    signal?.removeEventListener('abort', close);
172	  }
173	}
