179	function tool(name: string, description: string, properties: Record<string, unknown>, required: string[] = []): McpTool {
180	  return { name, description, inputSchema: { type: 'object', additionalProperties: false, properties, required } };
181	}
182	function response(request: JsonRpcRequest, result: Record<string, unknown>): JsonRpcResponse {
183	  return { jsonrpc: '2.0', id: request.id ?? null, result };
184	}
185	function failure(request: JsonRpcRequest, code: number, message: string): JsonRpcResponse {
186	  return { jsonrpc: '2.0', id: request.id ?? null, error: { code, message } };
187	}
188	function object(value: unknown): Record<string, unknown> { return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {}; }
189	function string(value: unknown, name: string): string { if (typeof value !== 'string' || !value.trim()) throw new Error(`${name} is required`); return value; }
190	function optionalString(value: unknown): string | undefined { return typeof value === 'string' && value.trim() ? value : undefined; }
191	function optionalNumber(value: unknown): number | undefined { return typeof value === 'number' && Number.isFinite(value) ? value : undefined; }
192	function enumValue<T extends string>(value: unknown, allowed: readonly T[], name: string): T {
