 37	async function execute(
 38	  client: MailFnClient,
 39	  command: string,
 40	  positionals: string[],
 41	  flags: Record<string, string | boolean | undefined>,
 42	): Promise<unknown> {
 43	  switch (command) {
 44	    case 'inbox:create':
 45	      return client.createInbox({
 46	        kind: flags.stable ? 'stable' : 'expiring',
 47	        requestedLocalPart: text(flags.local),
 48	        domain: text(flags.domain),
 49	        displayName: text(flags.name),
 50	        expirySeconds: number(flags.expires),
 51	        idempotencyKey: text(flags.idempotencyKey),
 52	      });
 53	    case 'inbox:list': return client.listInboxes();
 54	    case 'inbox:get': return client.getInbox(required(positionals[0], 'inbox id'));
 55	    case 'inbox:delete': return client.deleteInbox(required(positionals[0], 'inbox id'));
 56	    case 'message:list':
 57	      return client.listMessages(required(positionals[0], 'inbox id'), {
 58	        sender: text(flags.sender), subject: text(flags.subject), receivedAfter: text(flags.after),
 59	        unreadOnly: Boolean(flags.unread), limit: number(flags.limit),
 60	      });
 61	    case 'message:read': return client.readMessage(required(positionals[0], 'inbox id'), required(positionals[1], 'message id'));
 62	    case 'message:attachments': return client.listAttachments(required(positionals[0], 'inbox id'), required(positionals[1], 'message id'));
 63	    case 'message:wait':
