 67	      });
 68	    case 'message:extract':
 69	      return client.extractVerification(
 70	        required(positionals[0], 'inbox id'), required(positionals[1], 'message id'),
 71	        flags.link ? 'verification_link' : 'otp',
 72	      );
 73	    case 'token:revoke':
 74	      return client.revokeToken(required(positionals[0], 'inbox id'), required(positionals[1], 'token id'));
 75	    case 'domain:create': return client.createDomain(required(positionals[0], 'domain'));
 76	    case 'domain:verify': return client.verifyDomain(required(positionals[0], 'domain id'));
