 84	  command: string,
 85	  data: unknown,
 86	  flags: Record<string, string | boolean | undefined>,
 87	): void {
 88	  const safe = redactForCommand(command, data, Boolean(flags.showContent));
 89	  if (command === 'inbox:create') {
 90	    context.output.success('Inbox created');
 91	    context.output.info(JSON.stringify(safe, null, 2));
 92	    return;
 93	  }
 94	  if (command === 'message:extract') {
 95	    context.output.info(JSON.stringify(data, null, 2));
 96	    return;
 97	  }
 98	  context.output.info(JSON.stringify(safe, null, 2));
 99	}
