101	function redactForCommand(command: string, value: unknown, showContent: boolean): unknown {
102	  if (showContent || command === 'message:extract') return value;
103	  return redactSensitive(value, command.startsWith('message:'));
104	}
105	
106	function redactSensitive(value: unknown, messageSurface: boolean): unknown {
107	  if (value === null || typeof value !== 'object') return value;
108	  if (Array.isArray(value)) return value.map((entry) => redactSensitive(entry, messageSurface));
109	  const hidden = messageSurface
110	    ? /^(subject|headers|metadata|from|to|cc|bcc|replyTo|envelopeFrom|envelopeTo|textBody|htmlBody|rawObjectKey|authenticationResults|filename)$/i
111	    : /token|secret|verification|raw/i;
112	  return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([key, entry]) => [
113	    key,
114	    hidden.test(key) ? '[REDACTED]' : redactSensitive(entry, messageSurface),
115	  ]));
116	}
117	
118	function parse(args: string[]): {
119	  command: string;
120	  positionals: string[];
121	  flags: Record<string, string | boolean | undefined>;
122	} {
123	  const [noun, verb, ...rest] = args;
124	  if (!noun || noun === '--help' || noun === 'help') return { command: 'help', positionals: [], flags: {} };
125	  const command = verb && !verb.startsWith('-') ? `${noun}:${verb}` : noun;
126	  const values = verb && !verb.startsWith('-') ? rest : [verb, ...rest].filter(Boolean) as string[];
127	  const positionals: string[] = [];
128	  const flags: Record<string, string | boolean> = {};
129	  for (let index = 0; index < values.length; index += 1) {
130	    const value = values[index]!;
131	    if (!value.startsWith('--')) { positionals.push(value); continue; }
132	    const key = value.slice(2).replace(/-([a-z])/g, (_, letter: string) => letter.toUpperCase());
133	    const next = values[index + 1];
134	    if (next && !next.startsWith('--')) { flags[key] = next; index += 1; }
135	    else flags[key] = true;
136	  }
137	  return { command, positionals, flags };
138	}
139	
140	function required(value: string | undefined, name: string): string {
141	  if (!value) throw new Error(`Missing ${name}`);
142	  return value;
143	}
144	function text(value: string | boolean | undefined): string | undefined { return typeof value === 'string' ? value : undefined; }
145	function number(value: string | boolean | undefined): number | undefined {
146	  if (typeof value !== 'string') return undefined;
147	  const parsed = Number.parseInt(value, 10);
148	  if (!Number.isFinite(parsed)) throw new Error(`Invalid number: ${value}`);
149	  return parsed;
150	}
