    expect(pending).toMatchObject({ status: 'pending' });
    expect(await env.MAILFN_OBJECTS.get(pending!.rawObjectKey)).not.toBeNull();

    const batch = createMessageBatch('mailfn-parse', [{
      id: 'queue-message-1',
      timestamp: new Date(),
      body: jobs[0]!,
      attempts: 1,
    }]);
