    expect(results.filter((result) => result.status === 'rejected')).toMatchObject([{
      reason: { code: 'MAILFN_QUOTA_EXCEEDED' },
    }]);
    expect(await new D1MailFnStore(env.MAILFN_DB).listInboxes(bootstrap.project.id)).toHaveLength(1);
