 233	async function authenticate(request: Request, config: MailFnHttpHandlerConfig): Promise<Actor> {
 234	  const token = request.headers.get('authorization')?.replace(/^Bearer\s+/i, '');
 235	  if (!token) throw new MailFnError({ code: 'MAILFN_UNAUTHORIZED', message: 'Bearer credential is required', status: 401 });
 236	  if (config.adminToken && config.adminProjectId && constantEquals(token, config.adminToken)) {
 237	    return {
 238	      actorType: 'admin', actorId: 'cloudflare-admin', projectId: config.adminProjectId,
 239	      scopes: ['project:admin'],
 240	    };
 241	  }
 242	  return config.mailfn.authenticate(token);
 243	}
 244	
 245	function requireAdmin(request: Request, adminToken?: string): void {
 246	  const token = request.headers.get('authorization')?.replace(/^Bearer\s+/i, '');
 247	  if (!adminToken || !token || !constantEquals(token, adminToken)) {
 248	    throw new MailFnError({ code: 'MAILFN_UNAUTHORIZED', message: 'Administrative credential is required', status: 401 });
 249	  }
 250	}
 251	
 252	async function body<T>(request: Request): Promise<T> {
 253	  if (!request.headers.get('content-type')?.toLowerCase().includes('application/json')) {
 254	    throw new MailFnError({ code: 'MAILFN_VALIDATION_FAILED', message: 'Content-Type must be application/json', status: 415 });
 255	  }
 256	  try {
 257	    return (await request.json()) as T;
 258	  } catch (error) {
 259	    throw new MailFnError({ code: 'MAILFN_VALIDATION_FAILED', message: 'Request body is invalid JSON', status: 400, cause: error });
 260	  }
 261	}
 262	
 263	function json(data: unknown, requestId: string, status = 200): Response {
 264	  return Response.json({ ok: true, data, error: null, meta: { requestId, version: MAILFN_API_VERSION } }, {
 265	    status,
 266	    headers: { 'Cache-Control': 'no-store', 'X-Request-Id': requestId },
 267	  });
 268	}
 269	
 270	function errorResponse(error: unknown, requestId: string): Response {
 271	  const mailError = error instanceof MailFnError
 272	    ? error
 273	    : new MailFnError({ code: 'MAILFN_STORAGE_FAILED', message: 'MailFn request failed', status: 500, retryable: true, cause: error });
 274	  return Response.json({
 275	    ok: false,
 276	    data: null,
 277	    error: { code: mailError.code, message: mailError.message, retryable: mailError.retryable, details: mailError.details },
 278	    meta: { requestId, version: MAILFN_API_VERSION },
 279	  }, {
 280	    status: mailError.status,
 281	    headers: {
 282	      'Cache-Control': 'no-store',
 283	      'X-Request-Id': requestId,
 284	      ...(mailError.status === 429 ? { 'Retry-After': '1' } : {}),
 285	      ...(mailError.status === 401 ? { 'WWW-Authenticate': 'Bearer realm="mailfn"' } : {}),
 286	    },
 287	  });
 288	}
 289	
 290	function binary(data: Uint8Array, contentType: string, requestId: string, filename?: string): Response {
 291	  const bytes = Uint8Array.from(data);
 292	  return new Response(bytes.buffer, {
 293	    headers: {
 294	      'Content-Type': contentType,
 295	      'Content-Length': String(bytes.byteLength),
 296	      'Cache-Control': 'private, no-store',
 297	      'X-Content-Type-Options': 'nosniff',
 298	      'X-Request-Id': requestId,
 299	      ...(filename ? { 'Content-Disposition': `attachment; filename="${filename.replace(/["\\]/g, '_')}"` } : {}),
 300	    },
 301	  });
 302	}
 303	
 304	function cors(response: Response, request: Request, allowed: string[] = []): Response {
 305	  const origin = request.headers.get('origin');
 306	  if (!origin || !allowed.includes(origin)) return response;
 307	  const headers = new Headers(response.headers);
 308	  headers.set('Access-Control-Allow-Origin', origin);
 309	  headers.set('Access-Control-Allow-Headers', 'Authorization, Content-Type, X-Request-Id');
 310	  headers.set('Access-Control-Allow-Methods', 'GET, POST, PUT, PATCH, DELETE, OPTIONS');
 311	  headers.set('Vary', 'Origin');
 312	  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
 313	}
